pub(crate) struct GeneratedOperationDispatcher<'a> {
    app_config: Arc<AppConfig>,
    data_access_by_schema: &'a HashMap<String, Arc<DataAccess>>,
}

impl<'a> GeneratedOperationDispatcher<'a> {
    pub(crate) fn new(
        app_config: Arc<AppConfig>,
        data_access_by_schema: &'a HashMap<String, Arc<DataAccess>>,
    ) -> Self {
        Self {
            app_config,
            data_access_by_schema,
        }
    }
}

impl RuntimeOperationCatalog for GeneratedOperationDispatcher<'_> {
    fn list_operations(&self, include_disabled: bool) -> Vec<RuntimeOperation> {
        list_operations(include_disabled)
    }
}

#[async_trait]
impl RuntimeOperationDispatcher for GeneratedOperationDispatcher<'_> {
    async fn call_operation(
        &self,
        user: UserAuth,
        request: RuntimeOperationRequest,
    ) -> Result<Value, AppError> {
        call_operation(
            self.app_config.clone(),
            self.data_access_by_schema,
            user,
            request,
        )
        .await
    }
}

